                if "search " in prompt:
                    if search(prompt):
                        prompt("")

                #if "show " in prompt:
                #    prompt = split("/","")[1]
                #    search(prompt)

                if prompt == "" or len(prompt) < 1:
                    print("[*] No prompt given, type help, back, show options, or run to proceed.")
                    #prompt(back)

                # if we are using a normal module
                if module != "modules/install_update_all":
                  if "show options" in prompt:

