                            login_data = "<br>".join(result_list)

                        else:
                            continue
                    except:
                        break
                result = {"result":login_data}
                return JsonResponse(result)
            else:
                return HttpResponseRedirect("/eq/")
        else:
            return HttpResponseRedirect("/eq/")
    else:
        return HttpResponseRedirect("/eq/")

