        missinggroups = oldnames - currgroups
        if missinggroups:
            raise ValueError(
                'The following groups to rename do not exist: {0}'.format(
                    ','.join(missinggroups)))
        newnames = set([])
        for name in renamemap:
            newnames.add(renamemap[name])
        if newnames & currgroups:
