    ###########################################################################
    # some LEAR-specific queries
    ###########################################################################

    # load everything:
    lear_code_tables =  ['corp_types']
    # load by identifier (was corp_num)
    lear_corp_tables =  ['businesses',
                    'businesses_version']
    # load by business_id (id on businesses_version table)
    lear_other_tables = ['filings',
                    'aliases',
                    'aliases_version',
                    'party_roles',
                    'party_roles_version']
    # custom load
    lear_other_other_tables = ['parties',
                          'parties_version',]
    lear_other_other_other_tables = ['transaction',]

    # in colin if the corp_num is numeric we pre-pend 'BC' to it
    def bc_ifiy(self, specific_corps):
        corp_nums = []
        for corp_num in specific_corps:
            try:
                i = int(corp_num)
                corp_nums.append('BC' + corp_num)
            except:
                corp_nums.append(corp_num)
        return corp_nums

    # load all bc registries data for the specified corps into our in-mem cache
    def cache_lear_bcreg_corps(self, specific_corps, generate_individual_sql=False, use_sec=False):
        if self.use_local_cache():
            self.cache_lear_bcreg_corp_tables(specific_corps, generate_individual_sql=generate_individual_sql, use_sec=use_sec)
            self.cache_lear_bcreg_code_tables(generate_individual_sql=generate_individual_sql, use_sec=use_sec)

    # load all bc registries data for the specified corps into our in-mem cache
    def cache_lear_bcreg_corp_tables(self, specific_corps, generate_individual_sql=False, use_sec=False):
        if self.use_local_cache():
            # ensure we have a unique list
            specific_corps = list({s_corp for s_corp in specific_corps})
            specific_corps = self.bc_ifiy(specific_corps)
            specific_corps_lists = self.split_list(specific_corps, MAX_WHERE_IN)

            LOGGER.info('Caching data for parties and events ...')
            self.generated_sqls = []
            self.generated_corp_nums = {}
            LOGGER.info('Caching data for corporations ...')
            for corp_nums_list in specific_corps_lists:
                bus_ids_list = []
                txn_ids_list = []
                corp_nums_list_str = self.id_where_in(corp_nums_list, True)
                corp_num_where = 'identifier in (' + corp_nums_list_str + ')' if 0 < len(corp_nums_list_str) else "identifier = ''"
                corp_num_where_ex = corp_num_where + " or id in (select business_id from party_roles, parties where party_roles.party_id = parties.id and parties." + corp_num_where + ")"
                for corp_table in self.lear_corp_tables:
                    _rows = self.get_bcreg_table(corp_table, corp_num_where_ex, '', True, generate_individual_sql, use_sec=use_sec)
                    if corp_table == 'businesses':
                        for _row in _rows:
                            bus_ids_list.append(_row['id'])
                    elif corp_table == 'businesses_version':
                        for _row in _rows:
                            if _row['transaction_id'] is not None:
                                txn_ids_list.append(_row['transaction_id'])

                party_ids_list = []
                bus_id_where = 'business_id in (' + self.id_where_in(bus_ids_list, True) + ')' if 0 < len(bus_ids_list) else "business_id = 0"
                bus_id_where += " or business_id in (select business_id from party_roles, parties where party_roles.party_id = parties.id and parties." + corp_num_where + ")"
                for other_table in self.lear_other_tables:
                    _rows = self.get_bcreg_table(other_table, bus_id_where, '', True, generate_individual_sql, use_sec=use_sec)
                    if other_table == 'party_roles':
                        for _row in _rows:
                            if _row['party_id'] is not None:
                                party_ids_list.append(_row['party_id'])
                    elif other_table == 'filings':
                        for _row in _rows:
                            if _row['transaction_id'] is not None:
                                txn_ids_list.append(_row['transaction_id'])

                additional_identifiers = []
                party_id_where = 'id in (' + self.id_where_in(party_ids_list, True) + ')' if 0 < len(party_ids_list) else "id = 0"
                party_id_where += " or identifier in (" + self.id_where_in(corp_nums_list, True) + ")"
                for other_table in self.lear_other_other_tables:
                    _rows = self.get_bcreg_table(other_table, party_id_where, '', True, generate_individual_sql, use_sec=use_sec)
                    if other_table == 'parties':
                        for _row in _rows:
                            if _row['identifier'] is not None and 0 < len(_row['identifier']):
                                additional_identifiers.append(_row['identifier'])
                if 0 < len(additional_identifiers):
                    corp_nums_list_str = self.id_where_in(additional_identifiers, True)
                    corp_num_where = 'identifier in (' + corp_nums_list_str + ')'
                    for corp_table in self.lear_corp_tables:
                        _rows = self.get_bcreg_table(corp_table, corp_num_where, '', True, generate_individual_sql, use_sec=use_sec)

                txn_id_where = 'id in (' + self.id_where_in(txn_ids_list, True) + ')' if 0 < len(txn_ids_list) else "id = 0"
                for other_table in self.lear_other_other_other_tables:
                    _rows = self.get_bcreg_table(other_table, txn_id_where, '', True, generate_individual_sql, use_sec=use_sec)

    # load all bc registries data for the specified corps into our in-mem cache
    def cache_lear_bcreg_code_tables(self, generate_individual_sql=False, use_sec=False):
        if self.use_local_cache():
            LOGGER.info('Caching data for code tables ...')
            self.generated_sqls = []
            self.generated_corp_nums = {}
            for code_table in self.lear_code_tables:
                _rows = self.get_bcreg_table(code_table, '', '', True, generate_individual_sql, use_sec=use_sec)

from django.db import models
from kubernetes.client.apis import core_v1_api
from kubernetes  import client, config
from django.contrib.auth.models import User
from django.conf import settings
from kubernetes.client.rest import ApiException
import yaml 
import random
import logging
import os 

def get_kube_config():
    if os.path.isfile('/var/run/secrets/kubernetes.io/serviceaccount/token'):
        return config.load_incluster_config()
    else:
        return config.load_kube_config()


class UserService(models.Model):
    name          = models.CharField(max_length=200)
    port          = models.CharField(max_length=5)
    username      = models.ForeignKey(User, on_delete=models.CASCADE)
    password      = models.CharField(max_length=200)
    service       = models.CharField(max_length=10)
    path          = models.CharField(max_length=50)
    def __str__(self):
        return self.name

    class Meta:
        verbose_name_plural = "userService"

class Pynote:
    ## Model to create PyNote
    name = 'Pynote'
    get_kube_config()
    kube = client.ExtensionsV1beta1Api()
    api = core_v1_api.CoreV1Api()

    ## Environment is used for namespace
    environment = getattr(settings, 'ENVIRONMENT', None)
    namespace   = f'{environment}-students'


    def available_port(self):
        ## Function will find available port 
        while True:
            random_port = random.choice(list(range(7000, 7100)))
            if not UserService.objects.filter(port=random_port).first():
                return random_port


    def generate_templates(self, username, password, environment, service_path=None):
        ## Function generates all templates <pod>, <service>, <ingress>
        templates = {}
        template_port = self.available_port()
        host = f'{self.environment}.academy.fuchicorp.com'
        ingress_name  = f'{self.environment}-pynote-ingress'
        namespace     = f'{self.environment}-students'

        if service_path is None:
            templates['pynotelink'] = f'/services/pynotes/{username}'
            templates['path'] = {'path': f'/services/pynotes/{username}', 'backend': {'serviceName': username, 'servicePort': template_port}}
        else:
            templates['pynotelink'] = service_path
            templates['path'] = {'path': f'{service_path}', 'backend': {'serviceName': username, 'servicePort': template_port}}

        with open('kubernetes/pynote-pod.yaml' ) as file:
            pod = yaml.load(file, Loader=yaml.FullLoader)
            pod['metadata']['name']              = username
            pod['metadata']['labels']['run']     = username
            pod['spec']['containers'][0]['name'] = username
            pod['spec']['containers'][0]['args'] = [ f"--username={username}", f"--password={password}"]

            if service_path is None:
                pod['spec']['containers'][0]['env'].append({"name": "URL_PATH", "value": f'/services/pynotes/{username}'}) 
            else:
                pod['spec']['containers'][0]['env'].append({"name": "URL_PATH", "value": f'{service_path}'}) 

            templates['pod'] = pod

        with open('kubernetes/pynote-service.yaml') as file:
            service = yaml.load(file, Loader=yaml.FullLoader)
            service['metadata']['labels']['run'] = username
            service['spec']['ports'][0]['port']  = template_port
            service['spec']['selector']['run']   = username
            service['metadata']['name']          = username
            templates['service']                 = service

        with open('kubernetes/pynote-ingress.yaml') as file:
            ingress = yaml.load(file, Loader=yaml.FullLoader)
            ingress['spec']['rules'][0]['host']  = host
            ingress['spec']['rules'][0]['http']['paths'].append(templates['path'])
            ingress['metadata']['name']          = ingress_name
            ingress['metadata']['namespace']     = namespace
            templates['ingress']                 = ingress
        return templates

    def existing_ingess(self, ingerssname, namespace):
        list_ingress = self.kube.list_namespaced_ingress(namespace).items
        for item in list_ingress:
            if item.metadata.name == ingerssname:
                return item
        else:
            return False

    def create_service(self, username, password, service_path=None):
        ## Function to create service pynote 
        pynote_name    = username.lower()
        pynote_pass    = password
        ingress_name   = f'{self.environment}-pynote-ingress'
        namespace      = f'{self.environment}-students'

        if service_path is None:
            deployment = self.generate_templates(pynote_name, pynote_pass, self.environment)
        else:
            deployment = self.generate_templates(pynote_name, pynote_pass, self.environment, service_path)
        if not self.is_pod_exist(pynote_name):
            self.api.create_namespaced_pod(body=deployment['pod'], namespace=namespace)
        if not self.is_service_exist(pynote_name):
            self.api.create_namespaced_service(body=deployment['service'], namespace=namespace)
        exist_ingress  = self.existing_ingess(ingress_name, namespace)
        if exist_ingress:
            exist_ingress.spec.rules[0].http.paths.append(deployment['path'])
            self.kube.replace_namespaced_ingress(exist_ingress.metadata.name, namespace, body=exist_ingress)
        else:
            self.kube.create_namespaced_ingress(namespace, body=deployment['ingress'])
        return deployment

    def is_pod_exist(self, username):
        try:
            self.api.read_namespaced_pod(username, self.namespace)
            return True
        except ApiException:
            return False

    def is_service_exist(self, username):
        try:
            self.api.read_namespaced_service(username, self.namespace)
            return True
        except ApiException:
            return False

    def is_ingress_exist(self):
        try:
            self.kube.read_namespaced_ingress(f"{self.environment}-pynote-ingress", self.namespace)
            return True
        except ApiException:
            return False

    def delete_service(self, username):
        ## Function to delete the service
        pynote_name    = username.lower()
        ingress_name   = f'{self.environment}-pynote-ingress'
        namespace      = f'{self.environment}-students'
        exist_ingress  = self.existing_ingess(ingress_name, namespace)
        try:
            self.api.delete_namespaced_pod(pynote_name, namespace)
            logging.warning(f'Deleted a pod {pynote_name}')
            self.api.delete_namespaced_service(pynote_name, namespace)
            logging.warning(f'Deleted a service {pynote_name}')
        except:
            logging.warning('Trying to delete service and pod was not successed.')
        if exist_ingress:
            if 1 < len(exist_ingress.spec.rules[0].http.paths):
                for i in exist_ingress.spec.rules[0].http.paths:
                    if username in i.path:
                        exist_ingress.spec.rules[0].http.paths.remove(i)
                exist_ingress.metadata.resource_version = ''
                self.kube.patch_namespaced_ingress(exist_ingress.metadata.name, namespace, body=exist_ingress)
            else:
                self.kube.delete_namespaced_ingress(ingress_name, namespace)
        try:

            user = User.objects.get(username=username)
            service = UserService.objects.get(username=user).first()
            service.delete()  
            logging.warning(f"Pynote has been delete for {username}") 
        except Exception as e:
            logging.error(f"Error: {e}")      


