            date_closed=date_closed or timezone.now(),
        )
        for project in projects:
            IncidentProject.objects.create(incident=incident, project=project)
        if groups:
            for group in groups:
                IncidentGroup.objects.create(incident=incident, group=group)
        if seen_by:
            for user in seen_by:
                IncidentSeen.objects.create(incident=incident, user=user, last_seen=timezone.now())
        return incident

    @staticmethod
    def create_incident_activity(incident, type, comment=None, user=None):
        return IncidentActivity.objects.create(
            incident=incident, type=type, comment=comment, user=user
        )

    @staticmethod
    def create_alert_rule(
        organization,
        projects,
        name=None,
        threshold_type=AlertRuleThresholdType.ABOVE,
        query="level:error",
        aggregation=QueryAggregations.TOTAL,
        time_window=10,
        alert_threshold=100,
        resolve_threshold=10,
        threshold_period=1,
        include_all_projects=False,
        excluded_projects=None,
    ):
        if not name:
            name = petname.Generate(2, " ", letters=10).title()

        return create_alert_rule(
            organization,
            projects,
            name,
            threshold_type,
            query,
            aggregation,
            time_window,
            alert_threshold,
            resolve_threshold,
            threshold_period,
            include_all_projects=include_all_projects,
            excluded_projects=excluded_projects,
        )

